import { supabase } from './client'
import type { AppInstallation } from '@/entities/app/types'

export const marketplaceService = {
  async listInstallations(tenantId: string): Promise<AppInstallation[]> {
    const { data, error } = await supabase
      .from('app_installations')
      .select('*')
      .eq('tenant_id', tenantId)
    if (error) throw error
    return (data ?? []) as AppInstallation[]
  },

  async enableApp(tenantId: string, appId: string, enabledBy: string): Promise<void> {
    const { error } = await supabase.from('app_installations').upsert({
      tenant_id: tenantId,
      app_id: appId,
      enabled_by: enabledBy,
      status: 'active',
    })
    if (error) throw error
  },

  async disableApp(tenantId: string, appId: string): Promise<void> {
    const { error } = await supabase
      .from('app_installations')
      .update({ status: 'disabled' })
      .eq('tenant_id', tenantId)
      .eq('app_id', appId)
    if (error) throw error
  },
}
